import fs from 'node:fs/promises'
import { fileURLToPath } from 'node:url'
import { buildSquadImage } from '../frontend/src/features/matches/squadImage.ts'
import { formationOptions, formationLabel, pitchRowsFor } from '../frontend/src/features/matches/formations.ts'

// Synthetic-only previews generated by the same renderer used by the app.
const out = fileURLToPath(new URL('../docs/diagrams/squad-sharing/', import.meta.url))
await fs.mkdir(out, { recursive: true })
for (const formation of formationOptions) {
  const participants = Array.from({ length: 13 }, (_, i) => ({ playerId: i + 1, name: `예시${String(i + 1).padStart(2, '0')}`, shirtNumber: i + 1, playerType: 'MEMBER' }))
  const entries = pitchRowsFor(formation).flat().map((slot, i) => ({ team: 'A', quarterNumber: 1, slot, entryOrder: 0, playerId: i + 1 }))
  entries.push(...[0, 5].map((i, n) => ({ ...entries[i], entryOrder: 1, playerId: 12 + n })))
  const { svg } = buildSquadImage({ teamName: '예시 FC', playedOn: '2026-10-25', kickoff: '09:00', opponent: '상대 FC', internal: false, unsaved: true, quarter: 1, team: 'A', formationA: formation, entries, participants })
  await fs.writeFile(`${out}/${formation}.svg`, svg)
}
await fs.writeFile(`${out}/index.html`, `<!doctype html><html lang="ko"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>조축ON 스쿼드 이미지 · 개발 미리보기</title><style>body{margin:24px;background:#f7f8f4;color:#243c34;font-family:system-ui,sans-serif}main{max-width:1200px;margin:auto}.flow{padding:18px;background:#e8f2e8;border-radius:12px;line-height:1.8}.samples{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,320px),1fr));gap:20px}figure{margin:0}img{width:100%;height:auto;border-radius:14px}figcaption{font-weight:bold;margin:16px 0 8px}</style><main><h1>스쿼드 이미지 공유</h1><p>2026-10-19 · 개발 미리보기 / 미배포 · 모두 가상 선수</p><p class="flow">02 스쿼드 배치 → 스쿼드 이미지 → 구간·A/B팀 선택 → PNG 미리보기 → 이미지 공유 또는 PNG 다운로드<br>현재 입력을 반영하며 경기 저장과 별개. 저장 전이면 이미지에 명시. 외부 전송은 사용자가 공유 창에서 선택.</p><div class="samples">${formationOptions.map(f => `<figure><figcaption>${formationLabel(f)} · 선발과 교체</figcaption><img src="${f}.svg" alt="${formationLabel(f)} 스쿼드 이미지 예시"></figure>`).join('')}</div></main></html>`)
console.log('Generated six synthetic squad image previews and workflow page.')
